<template><main class="induction-booking"><section class="booking-shell"><header><span class="demo-data-badge">Frontend-only Bookings demo</span><h1>Bookings</h1><p>Choose an available service or use an invitation link.</p></header><template v-if="invitationToken"><p class="booking-lock"><strong>Booking type locked by invitation:</strong> {{type?.name||'Unavailable'}}. This invitation cannot be used for another service.</p><InductionBooking :invitation-token="invitationToken"/></template><template v-else-if="bookingTypeSlug"><section v-if="!type||type.status!=='active'" class="booking-state"><h2>Booking type unavailable</h2><p>This service is draft, inactive, or not available to your audience.</p></section><section v-else-if="type.invitationRequired" class="booking-state"><h2>Invitation required</h2><p>{{type.name}} can only be opened from a valid invitation. A direct URL cannot bypass this requirement.</p><RouterLink to="/bookings">Return to Bookings</RouterLink></section><section v-else class="booking-card"><h2>{{type.name}}</h2><p>{{type.shortDescription}}</p><p v-if="type.accountRequired">An account is required before booking.</p><p>No directly bookable fictional service is active in this demo.</p></section></template><template v-else><section class="booking-type-grid" aria-label="Available booking types"><article v-for="item in visibleTypes" :key="item.id" class="booking-card"><h2>{{item.name}}</h2><p>{{item.shortDescription}}</p><dl><div><dt>Access</dt><dd>{{item.accessType}}</dd></div><div><dt>Duration</dt><dd>{{item.duration}} minutes</dd></div><div><dt>Audience</dt><dd>{{item.audience}}</dd></div></dl><p v-if="item.invitationRequired">A valid invitation is required. Direct booking is unavailable.</p><RouterLink v-else :to="{name:'BookingsType',params:{bookingTypeSlug:item.slug}}">Book now</RouterLink></article><p v-if="!visibleTypes.length">No booking types are currently available to this visitor.</p></section></template></section></main></template>
<script>import InductionBooking from'../InductionBooking/InductionBooking.vue';import{getBookingType,listBookingTypes}from'../Admin/Bookings/bookingAvailabilityData.js';export default{name:'Bookings',components:{InductionBooking},props:{bookingTypeSlug:{type:String,default:''},invitationToken:{type:String,default:''}},computed:{type(){if(this.invitationToken)return getBookingType('induction');return getBookingType(this.bookingTypeSlug)},visibleTypes(){return listBookingTypes()}}};</script><style src="../InductionBooking/InductionBooking.css"></style>
